export const getGetRecordValueUrl = (resource: string,
    id: string,
    params: GetRecordValueParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/admin/${resource}/${id}/_value?${stringifiedParams}` : `/admin/${resource}/${id}/_value`
}

